import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";

import { checkWhatsappVideoCodecs } from "./video-codec";

/**
 * Real MP4s, generated by __fixtures__/video/generate.sh. The Go inspector in
 * services/wa-agent-bridge/internal/videocodec is tested against these same
 * files, so the two rules cannot drift on a real file without one suite going
 * red.
 */
function fixture(name: string): Uint8Array {
  return new Uint8Array(readFileSync(join(__dirname, "__fixtures__/video", name)));
}

function box(type: string, payload: Uint8Array): Uint8Array {
  const out = new Uint8Array(8 + payload.length);
  new DataView(out.buffer).setUint32(0, out.length);
  out.set(new TextEncoder().encode(type), 4);
  out.set(payload, 8);
  return out;
}

function concat(...parts: Uint8Array[]): Uint8Array {
  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
  let at = 0;
  for (const p of parts) {
    out.set(p, at);
    at += p.length;
  }
  return out;
}

/** Offset of the first top-level box of `type`. */
function topLevel(bytes: Uint8Array, type: string): number {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  for (let at = 0; at < bytes.length; at += view.getUint32(at)) {
    if (new TextDecoder().decode(bytes.subarray(at + 4, at + 8)) === type) return at;
  }
  throw new Error(`no ${type}`);
}

describe("checkWhatsappVideoCodecs — real files", () => {
  it.each([
    "h264-aac-faststart.mp4",
    "h264-aac-moov-at-end.mp4",
    "h264-no-audio.mp4",
  ])("allows %s", (name) => {
    expect(checkWhatsappVideoCodecs(fixture(name))).toEqual({ ok: true });
  });

  it.each(["hevc-hvc1-aac.mp4", "hevc-hev1-aac.mp4"])("refuses %s and names HEVC", (name) => {
    const r = checkWhatsappVideoCodecs(fixture(name));
    expect(r).toEqual({
      ok: false,
      code: "video_codec_unsupported",
      message: "This video is HEVC (H.265), which WhatsApp can't play. Export it as H.264 MP4 and try again.",
    });
  });

  it("refuses H.264 with Opus sound, naming the audio", () => {
    const r = checkWhatsappVideoCodecs(fixture("h264-opus.mp4"));
    expect(r).toMatchObject({ ok: false, code: "video_codec_unsupported" });
    expect(r.ok === false && r.message).toContain('sound is "Opus"');
  });

  it("refuses an mp4a with two esds instead of trusting a nested wave (the Go inspector must agree)", () => {
    // Two direct esds (MP3) plus wave{esds(AAC)}: ambiguous, so refused as
    // unconfirmed rather than resolved by the nested box. ffprobe calls it AAC.
    expect(checkWhatsappVideoCodecs(fixture("mp3-esds-twice-aac-in-wave.mp4"))).toEqual({
      ok: false,
      code: "video_codec_unsupported",
      message:
        "This video's sound couldn't be confirmed as AAC, which is all WhatsApp plays. Export it with AAC audio and try again.",
    });
  });

  it.each(["h264-mp3.mp4", "h264-aac-then-mp3.mp4"])("refuses %s — mp4a holding MP3 is not AAC", (name) => {
    expect(checkWhatsappVideoCodecs(fixture(name))).toEqual({
      ok: false,
      code: "video_codec_unsupported",
      message: "This video's sound is MP3, which WhatsApp can't play. Export it with AAC audio and try again.",
    });
  });

  it.each(["garbage.mp4", "truncated.mp4"])("refuses %s as unreadable without throwing", (name) => {
    expect(checkWhatsappVideoCodecs(fixture(name))).toMatchObject({ ok: false, code: "media_invalid" });
  });

  it("never allows any prefix of a real file, and never throws on one", () => {
    const bytes = fixture("h264-aac-faststart.mp4");
    for (let n = 0; n < bytes.length; n++) {
      expect(checkWhatsappVideoCodecs(bytes.subarray(0, n)).ok, `prefix ${n}`).toBe(false);
    }
  });

  it("refuses zero bytes as unreadable", () => {
    expect(checkWhatsappVideoCodecs(new Uint8Array())).toMatchObject({ ok: false, code: "media_invalid" });
  });
});

describe("checkWhatsappVideoCodecs — parses boxes, never scans bytes", () => {
  it("ALLOWS an H.264 file whose mdat contains the bytes hvc1 and hev1", () => {
    const bytes = fixture("h264-with-hevc-bytes-in-mdat.mp4");
    expect(Buffer.from(bytes).includes("hvc1")).toBe(true);
    expect(checkWhatsappVideoCodecs(bytes)).toEqual({ ok: true });
  });

  it("REFUSES an HEVC file whose mdat contains the bytes avc1 and mp4a", () => {
    const bytes = fixture("hevc-with-avc1-bytes-in-mdat.mp4");
    expect(Buffer.from(bytes).includes("avc1")).toBe(true);
    expect(checkWhatsappVideoCodecs(bytes)).toMatchObject({ ok: false, code: "video_codec_unsupported" });
  });

  it("follows a 64-bit largesize mdat header", () => {
    // `free`(8) + `mdat` header(8) rewritten as one 16-byte largesize mdat
    // header: same length, so every chunk offset still holds.
    const bytes = fixture("h264-aac-moov-at-end.mp4").slice();
    const free = topLevel(bytes, "free");
    const view = new DataView(bytes.buffer);
    const mdatSize = view.getUint32(free + 8);
    expect(new TextDecoder().decode(bytes.subarray(free + 12, free + 16))).toBe("mdat");
    view.setUint32(free, 1);
    bytes.set(new TextEncoder().encode("mdat"), free + 4);
    view.setBigUint64(free + 8, BigInt(8 + mdatSize));
    expect(checkWhatsappVideoCodecs(bytes)).toEqual({ ok: true });
  });

  it("accepts size 0 on the last box, meaning it runs to end of file", () => {
    const bytes = fixture("h264-aac-faststart.mp4").slice();
    const mdat = topLevel(bytes, "mdat");
    new DataView(bytes.buffer).setUint32(mdat, 0);
    expect(checkWhatsappVideoCodecs(bytes)).toEqual({ ok: true });
  });
});

/** Offset of the first esds in a file, and of its DecoderConfigDescriptor OTI byte. */
function esdsOti(bytes: Uint8Array): { esds: number; oti: number } {
  const esds = Buffer.from(bytes).indexOf("esds");
  // ffmpeg writes 4-byte expandable sizes: FullBox(4) · 0x03 size(4) ES_ID(2) flags(1) · 0x04 size(4) · OTI
  expect(bytes[esds + 8]).toBe(0x03);
  expect(bytes[esds + 16]).toBe(0x04);
  return { esds, oti: esds + 21 };
}

describe("checkWhatsappVideoCodecs — AAC is read from esds, not assumed from mp4a", () => {
  it.each([
    ["0x66", 0x66, true],
    ["0x67", 0x67, true],
    ["0x68", 0x68, true],
    ["0x6b", 0x6b, false],
    ["0x20", 0x20, false],
  ])("objectTypeIndication %s allowed: %s", (_label, oti, allowed) => {
    const bytes = fixture("h264-aac-faststart.mp4").slice();
    bytes[esdsOti(bytes).oti] = oti;
    expect(checkWhatsappVideoCodecs(bytes).ok).toBe(allowed);
  });

  it("names a non-AAC, non-MP3 object type by its number", () => {
    const bytes = fixture("h264-aac-faststart.mp4").slice();
    bytes[esdsOti(bytes).oti] = 0x20;
    const r = checkWhatsappVideoCodecs(bytes);
    expect(r.ok === false && r.message).toContain("not AAC (object type 0x20)");
  });

  it("refuses an mp4a with no esds as video_codec_unsupported", () => {
    const bytes = fixture("h264-aac-faststart.mp4").slice();
    bytes.set(new TextEncoder().encode("xxxx"), esdsOti(bytes).esds);
    expect(checkWhatsappVideoCodecs(bytes)).toMatchObject({ ok: false, code: "video_codec_unsupported" });
  });

  it("refuses, without throwing, an esds whose descriptor sizes overrun it", () => {
    const bytes = fixture("h264-aac-faststart.mp4").slice();
    const { esds } = esdsOti(bytes);
    bytes.set([0xff, 0xff, 0xff, 0x7f], esds + 9); // ES_Descriptor size ≈ 256 MiB
    expect(checkWhatsappVideoCodecs(bytes)).toMatchObject({ ok: false, code: "video_codec_unsupported" });
    bytes.set([0x80, 0x80, 0x80, 0x80], esds + 9); // a fifth size byte would be needed
    expect(checkWhatsappVideoCodecs(bytes)).toMatchObject({ ok: false, code: "video_codec_unsupported" });
  });
});

describe("checkWhatsappVideoCodecs — trailing padding", () => {
  it.each([1, 7])("tolerates %i trailing bytes after the last top-level box", (n) => {
    const bytes = concat(fixture("h264-aac-faststart.mp4"), new Uint8Array(n));
    expect(checkWhatsappVideoCodecs(bytes)).toEqual({ ok: true });
  });

  it("stays strict inside nested boxes", () => {
    // Grow moov by 3 bytes of trailing junk inside it: the trak walk must refuse.
    const src = fixture("h264-aac-faststart.mp4");
    const view = new DataView(src.buffer, src.byteOffset, src.byteLength);
    const moov = topLevel(src, "moov");
    const moovSize = view.getUint32(moov);
    const bytes = concat(src.subarray(0, moov + moovSize), new Uint8Array(3), src.subarray(moov + moovSize));
    new DataView(bytes.buffer).setUint32(moov, moovSize + 3);
    expect(checkWhatsappVideoCodecs(bytes)).toMatchObject({ ok: false, code: "media_invalid" });
  });
});

describe("checkWhatsappVideoCodecs — hostile structure", () => {
  it("refuses a box claiming more bytes than the buffer holds", () => {
    const bytes = fixture("h264-aac-faststart.mp4").slice();
    new DataView(bytes.buffer).setUint32(topLevel(bytes, "moov"), 0x7fffffff);
    expect(checkWhatsappVideoCodecs(bytes)).toMatchObject({ ok: false, code: "media_invalid" });
  });

  it("refuses a box whose size is smaller than its own header", () => {
    const bytes = new Uint8Array(16);
    new DataView(bytes.buffer).setUint32(0, 4);
    expect(checkWhatsappVideoCodecs(bytes)).toMatchObject({ ok: false, code: "media_invalid" });
  });

  it("refuses a largesize beyond the buffer", () => {
    const bytes = new Uint8Array(32);
    const view = new DataView(bytes.buffer);
    view.setUint32(0, 1);
    bytes.set(new TextEncoder().encode("moov"), 4);
    view.setBigUint64(8, BigInt(0xffff_ffff_ffff));
    expect(checkWhatsappVideoCodecs(bytes)).toMatchObject({ ok: false, code: "media_invalid" });
  });

  it("refuses 200,000 empty boxes promptly, bounded by the box budget", () => {
    const free = box("free", new Uint8Array());
    const bytes = new Uint8Array(free.length * 200_000);
    for (let i = 0; i < 200_000; i++) bytes.set(free, i * free.length);
    const started = Date.now();
    expect(checkWhatsappVideoCodecs(bytes)).toMatchObject({ ok: false, code: "media_invalid" });
    expect(Date.now() - started).toBeLessThan(1000);
  });

  it("refuses a trak nested 5,000 deep without recursing into it", () => {
    let inner: Uint8Array = new Uint8Array();
    for (let i = 0; i < 5_000; i++) inner = box("trak", inner);
    const bytes = concat(box("ftyp", new Uint8Array(8)), box("moov", inner), box("mdat", new Uint8Array(1)));
    expect(checkWhatsappVideoCodecs(bytes)).toMatchObject({ ok: false, code: "media_invalid" });
  });

  it("refuses a file with two moov boxes", () => {
    const moov = box("moov", new Uint8Array());
    expect(checkWhatsappVideoCodecs(concat(moov, moov))).toMatchObject({ ok: false, code: "media_invalid" });
  });
});
